PWR_DeInit.exampleCode:
/* 一般在调试时才需要：把 PWR 恢复到上电默认状态 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);
PWR_DeInit();

/* 复位后备份域访问被关闭，若要继续用 RTC/BKP 必须重新打开 */
PWR_BackupAccessCmd(ENABLE);

PWR_BackupAccessCmd.exampleCode:
/* 访问 BKP/RTC 的标准前置动作 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);

/* 关键：不开这个开关，后面所有对 BKP_DR / RTC 的写都是无效的 */
PWR_BackupAccessCmd(ENABLE);

/* 现在才能写备份寄存器 */
BKP_WriteBackupRegister(BKP_DR1, 0x1234);

PWR_PVDCmd.exampleCode:
/* 1. 打开 PWR 时钟 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);

/* 2. 设阈值 2.9V，并打开 PVD */
PWR_PVDLevelConfig(PWR_PVDLevel_2V9);
PWR_PVDCmd(ENABLE);

/* 3. 用 EXTI16 产生中断，掉电时抢救数据 */
EXTI_InitTypeDef EXTI_InitStructure;
EXTI_InitStructure.EXTI_Line = EXTI_Line16;
EXTI_InitStructure.EXTI_Mode = EXTI_Mode_Interrupt;
EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling;  /* 电压跌破阈值时触发 */
EXTI_InitStructure.EXTI_LineCmd = ENABLE;
EXTI_Init(&EXTI_InitStructure);

/* 4. 中断服务函数名固定为 PVD_IRQHandler */
/* void PVD_IRQHandler(void) { EXTI_ClearITPendingBit(EXTI_Line16); ... } */

PWR_PVDLevelConfig.exampleCode:
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);

/* 阈值设 2.9V：VDD 掉到 2.9V 以下就报警，此时还能跑几十毫秒 */
PWR_PVDLevelConfig(PWR_PVDLevel_2V9);
PWR_PVDCmd(ENABLE);

/* 轮询方式使用 */
if (PWR_GetFlagStatus(PWR_FLAG_PVDO) != RESET)
{
  /* 电压已低于阈值，赶紧把关键数据写进 BKP_DR */
}

PWR_WakeUpPinCmd.exampleCode:
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);

/* 使能 PA0 唤醒功能：PA0 上升沿把芯片从 STOP/STANDBY 唤醒 */
PWR_WakeUpPinCmd(ENABLE);

/* 进入待机，等待 PA0 上升沿或 RTC 闹钟 */
PWR_EnterSTANDBYMode();

/* 唤醒后相当于复位重启，可以通过 PWR_FLAG_WU 判断是唤醒引脚唤醒的 */
if (PWR_GetFlagStatus(PWR_FLAG_WU) != RESET)
{
  PWR_ClearFlag(PWR_FLAG_WU);
}

PWR_EnterSTOPMode.exampleCode:
/* ---- 进入 STOP 前：配好唤醒源（以 PA0 按键 EXTI0 为例） ---- */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);
GPIO_InitTypeDef GPIO_InitStructure;
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPD;      /* 下拉输入 */
GPIO_Init(GPIOA, &GPIO_InitStructure);

GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);
EXTI_InitTypeDef EXTI_InitStructure;
EXTI_InitStructure.EXTI_Line = EXTI_Line0;
EXTI_InitStructure.EXTI_Mode = EXTI_Mode_Interrupt;
EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Rising;
EXTI_InitStructure.EXTI_LineCmd = ENABLE;
EXTI_Init(&EXTI_InitStructure);

NVIC_InitTypeDef NVIC_InitStructure;
NVIC_InitStructure.NVIC_IRQChannel = EXTI0_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

/* ---- 打开 PWR 时钟后进入 STOP ---- */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);
PWR_EnterSTOPMode(PWR_Regulator_ON, PWR_STOPEntry_WFI);

/* ---- 被唤醒：时钟已切回 HSI，必须恢复时钟 ---- */
SystemInit();                                  /* 回到 72MHz HSE+PLL */
/* 注意：唤醒后外设时钟寄存器（RCC_APBxENR）内容保留，
   但如果你的重配函数里做了 RCC_DeInit，就要把所有外设时钟重新打开 */

PWR_EnterSTANDBYMode.exampleCode:
/* ---- 唤醒后第一件事：判断是不是从待机唤醒的 ---- */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
if (PWR_GetFlagStatus(PWR_FLAG_SB) != RESET)
{
  PWR_ClearFlag(PWR_FLAG_SB);            /* 清掉，否则下次醒来还会误判 */
  /* 从 BKP_DR1 取回休眠前保存的数据 */
  uint16_t saved = BKP_ReadBackupRegister(BKP_DR1);
}

/* ---- 准备休眠 ---- */
PWR_BackupAccessCmd(ENABLE);
BKP_WriteBackupRegister(BKP_DR1, 0x5A5A); /* RAM 会丢，数据放备份寄存器 */
PWR_WakeUpPinCmd(ENABLE);                /* PA0 上升沿或 RTC 闹钟唤醒 */

/* 进入待机：之后的代码不会再执行，醒来是从 main 重新开始 */
PWR_EnterSTANDBYMode();

PWR_GetFlagStatus.exampleCode:
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);

/* 判断本次复位是不是从待机模式唤醒造成的 */
if (PWR_GetFlagStatus(PWR_FLAG_SB) != RESET)
{
  PWR_ClearFlag(PWR_FLAG_SB);   /* 必须清，否则会一直误判 */
  /* 从待机唤醒：重新初始化外设并处理业务 */
}

/* 判断是不是 WKUP 引脚唤醒的 */
if (PWR_GetFlagStatus(PWR_FLAG_WU) != RESET)
{
  PWR_ClearFlag(PWR_FLAG_WU);
}

PWR_ClearFlag.exampleCode:
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);

/* 一次清两个标志，避免遗漏 */
PWR_ClearFlag(PWR_FLAG_WU | PWR_FLAG_SB);

/* 正确顺序：先读、再清、最后处理业务 */
if (PWR_GetFlagStatus(PWR_FLAG_SB) != RESET)
{
  PWR_ClearFlag(PWR_FLAG_SB);
  /* 处理待机唤醒后的逻辑 */
}
